from transformers import pipeline

print("Loading model (first run downloads about 500 MB)...")
detector = pipeline(
    "text-classification",
    model="Hello-SimpleAI/chatgpt-detector-roberta",
    top_k=None,
)

texts = {
    "Sample 1": "PASTE A PARAGRAPH YOU WROTE YOURSELF HERE",
    "Sample 2": "PASTE A PARAGRAPH GENERATED BY AN AI CHATBOT HERE",
}

for name, text in texts.items():
    results = detector(text, truncation=True, max_length=512)[0]
    print(f"\n{name}")
    for r in results:
        print(f"  {r['label']}: {r['score'] * 100:.1f}%")